Translate("deDE", "scarlet-monastery", {
	title = "Das Scharlachrote Kloster",
	aliases = { "Scharlachrotes Kloster" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Das Scharlachrote Kloster erhebt sich auf den nordöstlichen Höhen von {link:tirisfal-glades}Tirisfal{/link}, ein großes Haus aus grauem Stein hinter hohen Mauern. Einst war es ein Ort der Gelehrsamkeit und des Gebets, wo die Priesterschaft von {link:lordaeron}Lordaeron{/link} ihre Bücher aufbewahrte und junge Paladine in den Wegen des {link:holy-light}Heiligen Lichts{/link} ausbildete. Nun ist es die Festung und das schlagende Herz des {link:scarlet-crusade}Scharlachroten Kreuzzugs{/link}. Seine Glocken läuten noch. Seine Hallen sind voller Kreuzritter in Rot, und niemand, der ohne den Wappenrock des Kreuzzugs eintritt, ist willkommen.]=],
		},
		{
			title = "Ursprünge",
			text = [=[Keine Chronik verzeichnet das Jahr, in dem das Kloster gegründet wurde. Vor der Seuche zählte es zu den stolzesten Sitzen des Glaubens von {link:lordaeron}Lordaeron{/link}, eine Bastion des Wissens, verborgen in den Lichtungen. Gelehrte kamen in seine Bibliothek. Paladine in Ausbildung studierten in seinen Hallen. Als der {link:third-war}Dritte Krieg{/link} die {link:scourge}Geißel{/link} und den {link:fall-of-lordaeron}Fall Lordaerons{/link} brachte, rissen die Eiferer des Kreuzzugs das Kloster an sich und machten es zu einer Festung. Sie glauben, dass jeder Fremde die Seuche in sich tragen könnte, und sie behandeln jedes Volk außer ihrem eigenen als Feind.]=],
		},
		{
			title = "Die Gegenwart",
			text = [=[Das Kloster ist die wichtigste Bastion des Kreuzzugs in {link:tirisfal-glades}Tirisfal{/link}. Von hier schickt er seine Patrouillen und Boten zu den Türmen der Lichtungen, und er führt Krieg gegen die {link:forsaken}Verlassenen{/link} vor den Toren ihrer eigenen {link:capital-city}Hauptstadt{/link}. Der Scharlachrote Kommandant {link:scarlet-commander-mograine}Mograine{/link} führt seine Garnison. Seine wahre Herrin ist {link:high-inquisitor-whitemane}Hochinquisitorin Whitemane{/link}, eine Priesterin, von der es heißt, sie erwecke die Gefallenen auf ihren Befehl hin, damit sie erneut kämpfen. In {link:undercity}Undercity{/link} will {link:varimathras}Varimathras{/link} Whitemane und ihre obersten Leutnants tot sehen. In {link:southshore}Southshore{/link} will {link:raleigh-the-devout}Raleigh the Devout{/link}, der einst hier diente, dasselbe. Gelehrte der {link:horde}Horde{/link} wie der {link:alliance}Allianz{/link} wollen, was von der Bibliothek geblieben ist. Die Verlassenen wollen Herzen, Bücher und Rache.]=],
		},
		{
			title = "Innerhalb des Klosters",
			text = [=[• {b}Der Friedhof.{/b} Hinter dem Kloster liegt seine Begräbnisstätte. Die Befrager des Kreuzzugs arbeiten in ihren Grüften, und die ruhelosen Toten wandeln zwischen den Gräbern.
• {b}Die Bibliothek.{/b} Die große Bibliothek birgt noch immer die alten Bücher des Klosters, bewacht vom Hundemeister und vom Arkanisten des Kreuzzugs.
• {b}Die Waffenkammer.{/b} Hier bildet der Kreuzzug seine Rekruten aus und bewaffnet seine Krieger, unter den Augen seines Champions.
• {b}Die Kathedrale.{/b} Im Herzen des Klosters halten {link:scarlet-commander-mograine}Mograine{/link} und {link:high-inquisitor-whitemane}Whitemane{/link} das Heiligtum des Kreuzzugs.]=],
		},
	},
})

Translate("deDE", "scarlet-monastery-graveyard", {
	title = "Friedhof des Scharlachroten Klosters",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Friedhof des Klosters liegt zwischen zerbrochenen Grabmälern und Grüften. Der Kreuzzug lässt seine Toten hier nicht in Frieden ruhen. Seine Befrager haben die Grüfte zu einem Ort der Qual gemacht, wo verlassene Gefangene leiden, bis sie sagen, was sie wissen, oder bis nichts mehr von ihnen übrig ist. Auch die Toten des Hofes sind ruhelos. Gequälte Geister und Phantome treiben zwischen den Mausoleen umher, und ein untoter Blutmagier ruft in der tiefsten Gruft nach Seelen. Manche der Toten sind uralt. Manche, wie der gefallene Champion, der dort wandelt, trugen einst die Farben des Kreuzzugs selbst.]=],
		},
	},
})

Translate("deDE", "scarlet-monastery-library", {
	title = "Bibliothek des Scharlachroten Klosters",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Bibliothek ist, was von der alten Gelehrsamkeit des Klosters geblieben ist. Ihre Regale bergen Werke der Geschichte, der Überlieferung und des Rituals, über lange Jahre gesammelt, und manche davon sind von unschätzbarem Wert: eine Mythologie der Titanen, ein Kompendium der Gefallenen, eine Fibel über die ersten Tage der Bedrohung durch die Untoten, ein Buch der Rituale eines Magiers. Der Kreuzzug benutzt die Bücher, um seine Paladine gegen die Toten auszubilden. Niemand sonst darf sie lesen. Die Spürhunde des Hundemeisters streifen durch die äußeren Kreuzgänge, und der Arkanist bewacht die innere Halle.]=],
		},
	},
})

Translate("deDE", "scarlet-monastery-armory", {
	title = "Waffenkammer des Scharlachroten Klosters",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[In der Waffenkammer schmiedet der Kreuzzug seine Soldaten. Auf ihren Übungsplätzen hallen die Drills. Myrmidonen, Verteidiger und Zenturionen bewachen ihre Hallen, und die Waffen des Kreuzzugs lagern in ihren Gewölben. {link:herod}Herod{/link}, der Scharlachrote Champion, herrscht hier, und die Waffen des Kreuzzugs sind ihm zu vergeben. Er ist der beste Krieger des Klosters, und eine Schar junger Rekruten beobachtet ihn und wartet darauf, gerufen zu werden. Hier macht der Kreuzzug aus trauernden Bauern und Waisen Eiferer in Rot.]=],
		},
	},
})

Translate("deDE", "scarlet-monastery-cathedral", {
	title = "Kathedrale des Scharlachroten Klosters",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Kathedrale ist das Heiligtum des Klosters und der Sitz seiner Herren. Ihre Gärten und ihr Hof sind dicht besetzt mit Mönchen, Kaplänen, Äbten und Champions des Kreuzzugs. Jenseits von ihnen, in der großen Kapelle, wartet der Scharlachrote Kommandant {link:scarlet-commander-mograine}Mograine{/link} vor dem Altar, und {link:high-inquisitor-whitemane}Hochinquisitorin Whitemane{/link} wartet dahinter. Wer die Kapelle erreicht, verlässt sie selten wieder. Noch weiter, in einer Kammer, die nur wenige je sehen, weilt ein zweiter Hochinquisitor, {link:high-inquisitor-fairbanks}Fairbanks{/link}. Wer die Kathedrale hält, hält das Kloster.]=],
		},
	},
})

Translate("deDE", "high-inquisitor-whitemane", {
	title = "Hochinquisitorin Whitemane",
	subtitle = "Wahre Herrin des Klosters",
	found = "Die große Kapelle der Kathedrale des Scharlachroten Klosters",
	hint = [=[Erfahrt von ihr durch die Feinde des Kreuzzugs, oder sucht sie in der Kapelle der Kathedrale.]=],
	allegiance = "Scharlachroter Kreuzzug",
	aliases = { "Whitemane" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Hochinquisitorin Whitemane ist die wahre Herrin des {link:scarlet-monastery}Scharlachroten Klosters{/link}. {link:scarlet-commander-mograine}Mograine{/link} führt seine Soldaten, doch es ist Whitemane, der der Kreuzzug in {link:tirisfal-glades}Tirisfal{/link} gehorcht. Sie ist eine Priesterin von furchterregender Macht. Sie heilt ihre Champions, schirmt sie ab, versetzt ihre Feinde in tiefen Schlaf und beugt ihren Geist ihrem Willen. Am meisten gefürchtet ist ihre Gabe über den Tod selbst. Wenn ihre Krieger fallen, erweckt sie sie wieder, damit sie in ihrem Namen kämpfen.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Whitemane ist das Oberhaupt der Inquisition des Kreuzzugs in {link:tirisfal-glades}Tirisfal{/link}. Ihre Inquisitoren suchen die Seuche in jedem, dem sie begegnen, und sie finden sie, wo immer sie hinsehen. Unter ihrer Herrschaft wurde das Kloster zu einem Ort, an dem unschuldige Männer und Frauen gefoltert wurden, weil sie nicht den Wappenrock des Kreuzzugs trugen. Für die Verlassenen ist sie der Hauptfeind vor ihrer Tür. Für jene Lebenden, die einst dem Kreuzzug dienten, ist sie der Beweis, wie tief er gefallen ist.]=],
		},
		{
			title = "Taten",
			text = [=[• Sie hält das Kloster für den {link:scarlet-crusade}Scharlachroten Kreuzzug{/link}, mit {link:scarlet-commander-mograine}Mograine{/link} an ihrer Seite.
• Sie beherrscht eine Inquisition, die jeden Fremden als Träger der Seuche behandelt.
• Sie ruft das Licht an, um ihre Feinde zu strafen, zu heilen und zu schützen.
• Sie erweckt ihren gefallenen Champion vom Tod, damit er erneut kämpft.]=],
		},
		{
			title = "Nicht überliefert",
			text = [=[Keine Chronik dieser Tage verzeichnet Whitemanes Leben vor dem Kreuzzug, das Jahr, in dem sie Hochinquisitorin wurde, oder wo sie ihre Macht über die Gefallenen erlernte.]=],
		},
	},
	chapters = {
		{
			title = "Der schärfste Dorn",
			hint = [=[Hört, was der Schreckenslord von Undercity in Tirisfal getan haben will.]=],
			text = [=[Während {link:sylvanas-windrunner}die Dunkle Fürstin{/link} den Lichkönig im Norden beobachtete, wandte sich {link:varimathras}Varimathras{/link} den Feinden zu, die der Heimat am nächsten waren. Er nannte den Kreuzzug den schärfsten {link:dorn-plainstalker}Dorn{/link} im Fleisch der Verlassenen und rote Ameisen, die über die Lichtungen schwärmen. Er wollte Whitemane tot sehen, ein für alle Mal, und jeden ihrer obersten Leutnants mit ihr.]=],
		},
		{
			title = "Das wahnsinnige Regime",
			hint = [=[Hört die Geschichte des Kreuzritters, der das Kloster verließ.]=],
			text = [=[{link:raleigh-the-devout}Raleigh{/link} the Devout diente einst mit Stolz im Kloster. Er sah zu, wie dessen Anführer den Halt an der Wahrheit verloren. Er sah Unschuldige, die im Namen der Reinheit gefoltert wurden. Er ging, und er kam zu der Überzeugung, dass der Kreuzzug nicht geheilt werden würde, solange jene lebten, die ihn führten. Whitemane war der erste Name, den er nannte. Erst wenn sie gefallen sei, sagte er, könne die wahre Sache neu entfacht werden.]=],
		},
		{
			title = "Erhebe dich",
			hint = "Stellt Euch der Hochinquisitorin in ihrer Kapelle.",
			text = [=[Wenn {link:scarlet-commander-mograine}Mograine{/link} vor ihrem Altar fällt, tritt Whitemane voller Zorn hervor und nennt es Verrat. Sie wiegt ihre Feinde in Schlaf. Dann kniet sie über ihrem Kommandanten nieder und ruft das Licht an, und Mograine erhebt sich, um noch einmal an ihrer Seite zu kämpfen.]=],
		},
	},
	mentions = {
		{ text = "In das Scharlachrote Kloster" },
		{ text = "Im Namen des Lichts" },
	},
	bonds = {
		{ id = "scarlet-commander-mograine", name = "Scharlachroter Kommandant Mograine", note = "ihr Kommandant" },
		{ id = "high-inquisitor-fairbanks", name = "Hochinquisitor Fairbanks", note = "teilt ihren Rang" },
		{ id = "varimathras", name = "Varimathras", note = "will sie tot sehen" },
		{ id = "raleigh-the-devout", name = "Raleigh the Devout", note = "diente einst unter ihr" },
	},
})

Translate("deDE", "scarlet-commander-mograine", {
	title = "Scharlachroter Kommandant Mograine",
	subtitle = "Kommandant des Klosters",
	found = "Vor dem Altar der Kathedrale des Scharlachroten Klosters",
	hint = [=[Erfahrt von ihm durch die Feinde des Kreuzzugs, oder stellt Euch ihm vor dem Altar der Kathedrale.]=],
	allegiance = "Scharlachroter Kreuzzug",
	aliases = { "Mograine" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Scharlachrote Kommandant Mograine führt die Garnison des {link:scarlet-monastery}Scharlachroten Klosters{/link}, ein großes Heer von Kriegern, die dem Kreuzzug jenseits aller Vernunft ergeben sind. Er ist ein Paladin des {link:holy-light}Heiligen Lichts{/link}, in Plattenrüstung gehüllt und grimmig im Kampf. Er steht vor dem Altar der Kathedrale, umgeben von seinen Soldaten, und er begrüßt jeden Fremden als Ungläubigen, der geläutert werden muss.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Mograine ist das Schwert des Klosters, wie {link:high-inquisitor-whitemane}Whitemane{/link} sein Wille ist. Die Mönche, Äbte und Champions der Kathedrale gehören ihm, ebenso das Heer, das seine Tore hält. Seine Soldaten sind keine Söldner. Sie sind Eiferer, die wie er glauben, dass die Seuche in jedem Fremden lauert, und sie sterben lieber, als eine einzige Halle preiszugeben. Er kämpft mit der vollen Kraft eines Ritters des Lichts, desselben Lichts, das die Paladine von {link:lordaeron}Lordaeron{/link} einst gegen die {link:scourge}Geißel{/link} trugen. Diese Kraft dient nun einem Orden, der Unschuldige foltert. Die Feinde des Kreuzzugs, Lebende wie Tote, nennen ihn unter den Ersten, die fallen müssen. Für die Verlassenen ist er ein Eiferer, der niedergestreckt werden muss. Für {link:raleigh-the-devout}Raleigh{/link} the Devout, der einst unter ihm diente, ist er einer der Männer, die den Kreuzzug in die Irre führten.]=],
		},
		{
			title = "Taten",
			text = [=[• Er befehligt die Garnison des Scharlachroten Klosters.
• Er kämpft umgeben von der Aura der Vergeltung, und er schlägt zu wie ein Kreuzritter des Lichts.
• Wenn er dem Tod nahe ist, kann er das Licht anrufen, um sich von jeder Wunde zu heilen.
• Er kämpft an der Seite von {link:high-inquisitor-whitemane}Whitemane{/link}, die ihn erwecken kann, wenn er fällt.]=],
		},
		{
			title = "Nicht überliefert",
			text = [=[Keine Chronik dieser Tage verzeichnet Mograines Vornamen, seine Taten vor dem Kreuzzug oder wie er dazu kam, das Kloster zu befehligen.]=],
		},
	},
	chapters = {
		{
			title = "Ihre oberste Riege",
			hint = [=[Hört, was der Schreckenslord von Undercity in Tirisfal getan haben will.]=],
			text = [=[{link:varimathras}Varimathras{/link} wollte nicht {link:high-inquisitor-whitemane}Whitemane{/link} allein. Er wollte auch die Anführer um sie herum beseitigt sehen, und er nannte Mograine als Ersten unter ihnen: einen Eiferer, der in seinem eigenen Heiligtum niedergestreckt werden sollte.]=],
		},
		{
			title = "Der Kommandant fällt",
			hint = [=[Hört die Geschichte des Kreuzritters, der das Kloster verließ.]=],
			text = [=[Für {link:raleigh-the-devout}Raleigh{/link} the Devout war Mograine einer der höchsten Amtsträger eines wahnsinnig gewordenen Regimes. Solange solche Männer das Kloster hielten, sagte er, sei jeder in Gefahr, der den Weg des Kreuzzugs kreuze.]=],
		},
		{
			title = "Vor dem Altar",
			hint = [=[Stellt Euch dem Kommandanten in der großen Kapelle der Kathedrale.]=],
			text = [=[Mograine empfängt Eindringlinge am Altar und nennt sie Ungläubige. Wenn er fällt, kommt die Hochinquisitorin, um ihn zu rächen. Sie lässt ihn nicht tot bleiben. Von ihrer Hand erweckt, erhebt er sich und kehrt an ihre Seite zurück.]=],
		},
	},
	mentions = {
		{ text = "In das Scharlachrote Kloster" },
		{ text = "Im Namen des Lichts" },
	},
	bonds = {
		{ id = "high-inquisitor-whitemane", name = "Hochinquisitorin Whitemane", note = "seine Herrin" },
		{ id = "herod", name = "Herod", note = "Champion des Klosters" },
		{ id = "varimathras", name = "Varimathras", note = "will ihn tot sehen" },
		{ id = "raleigh-the-devout", name = "Raleigh the Devout", note = "will ihn tot sehen" },
	},
})

Translate("deDE", "herod", {
	title = "Herod",
	subtitle = "Der Scharlachrote Champion",
	found = "Die Waffenkammer des Scharlachroten Klosters",
	hint = [=[Sucht den Champion des Kreuzzugs in der Waffenkammer des Klosters.]=],
	allegiance = "Scharlachroter Kreuzzug",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Herod ist der Scharlachrote Champion, der mächtigste Krieger des {link:scarlet-monastery}Scharlachroten Klosters{/link}. Er herrscht über dessen Waffenkammer, wo der Kreuzzug seine Soldaten ausbildet und bewaffnet. Er ist ein Riese in Plattenrüstung, der mit einer großen Axt kämpft. Er wirbelt in einem Sturm aus Klingen durch seine Feinde, stürmt auf sie los und wird nur umso wilder, je mehr er blutet.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Herod ist das Vorbild des Kreuzzugs dafür, wie ein Krieger sein sollte. Die Rekruten der Waffenkammer üben unter seinen Augen und warten auf sein Wort. Die Myrmidonen, Verteidiger und Zenturionen, die die Hallen der Waffenkammer bewachen, unterstehen ihm, und er entscheidet, welche der jungen Rekruten bereit sind, die Waffen des Kreuzzugs aufzunehmen. Er ist einer der vier Anführer des Klosters, deren Tod sowohl {link:varimathras}Varimathras{/link} als auch {link:raleigh-the-devout}Raleigh the Devout{/link} fordern. Er sehnt sich nach einem würdigen Gegner, und er ruft das Licht an, ihm Kraft zu geben, selbst während er seine Feinde niederstreckt.]=],
		},
		{
			title = "Taten",
			text = [=[• Er befehligt die Waffenkammer des Klosters und ihre Übungsplätze.
• Er wirbelt durch seine Feinde, spaltet sie und stürmt auf sie los.
• In seiner Raserei wird er stärker, je tiefer seine Wunden werden.
• Wenn er fällt, stürmen die Rekruten der Waffenkammer herbei, um ihn zu rächen.]=],
		},
		{
			title = "Nicht überliefert",
			text = [=[Keine Chronik dieser Tage verzeichnet, woher Herod kam oder wie er seinen Titel errang.]=],
		},
	},
	chapters = {
		{
			title = "Die Herausforderung des Champions",
			hint = "Stellt Euch dem Champion in der Waffenkammer des Klosters.",
			text = [=[Herod begrüßt Eindringlinge mit Freude, denn er hat lange auf eine echte Herausforderung gewartet. Er kämpft gern. Wenn er endlich stirbt, strömen seine Rekruten in die Halle, jung und unerfahren, um zu vollenden, was ihr Champion nicht vermochte.]=],
		},
	},
	mentions = {
		{ text = "In das Scharlachrote Kloster" },
		{ text = "Im Namen des Lichts" },
	},
	bonds = {
		{ id = "scarlet-commander-mograine", name = "Scharlachroter Kommandant Mograine", note = "sein Kommandant" },
		{ id = "high-inquisitor-whitemane", name = "Hochinquisitorin Whitemane", note = "Herrin des Klosters" },
	},
})

Translate("deDE", "high-inquisitor-fairbanks", {
	title = "Hochinquisitor Fairbanks",
	subtitle = "Der verborgene Inquisitor",
	found = "Eine verborgene Kammer jenseits der Kapelle der Kathedrale",
	hint = [=[Sucht jenseits des Altars der Kathedrale nach einem zweiten Inquisitor.]=],
	allegiance = "Scharlachroter Kreuzzug",
	aliases = { "Fairbanks" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Hochinquisitor Fairbanks weilt in der {link:scarlet-monastery-cathedral}Kathedrale des Scharlachroten Klosters{/link}, in einer Kammer jenseits der Kapelle, in der {link:high-inquisitor-whitemane}Whitemane{/link} Hof hält. Nur wenige wissen, dass er dort ist. Er trägt denselben Rang wie Whitemane, den Titel eines Hochinquisitors, doch sie ist es, die über das Kloster herrscht, und er ist es, der verborgen gehalten wird. Er ist bleich wie ein Leichnam, und seine Stimme ist die hohle Stimme der Toten.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Fairbanks ist ein Rätsel im Herzen des Kreuzzugs. Im Kloster trägt nur {link:high-inquisitor-whitemane}Whitemane{/link} denselben Titel. Der Kreuzzug verbrennt die Untoten, wo immer er sie findet, und doch lebt ein Hochinquisitor mit dem Aussehen der Toten in seinem eigenen Heiligtum. Er ist dennoch ein Priester von großem Können. Er schirmt und heilt sich selbst, legt einen Blutfluch auf seine Feinde, versetzt sie in Schlaf und treibt sie in Schrecken davon.]=],
		},
		{
			title = "Taten",
			text = [=[• Er trägt den Rang eines Hochinquisitors des Kreuzzugs.
• Er hält sich in einer abgesonderten Kammer jenseits des Altars der Kathedrale auf.
• Er verflucht seine Feinde, versetzt sie in Schrecken und in Schlaf, und er heilt seine eigenen Wunden.]=],
		},
		{
			title = "Nicht überliefert",
			text = [=[Keine Chronik dieser Tage verzeichnet, wer Fairbanks war, warum er Whitemanes Rang teilt oder warum er vor dem Rest des Klosters verborgen gehalten wird.]=],
		},
	},
	chapters = {
		{
			title = "Die Kammer dahinter",
			hint = "Findet den Inquisitor, der jenseits der Kapelle wartet.",
			text = [=[Hinter dem Altar, wo {link:scarlet-commander-mograine}Mograine{/link} und {link:high-inquisitor-whitemane}Whitemane{/link} fielen, liegt eine Tür, und hinter der Tür wartet Fairbanks. Er kämpft allein, ohne Wachen und ohne das Heer, das Mograine dient. Was er über den Kreuzzug weiß und warum dieser ihn verborgen hält, behält er für sich. Wer seine Kammer verlässt, nimmt nur weitere Fragen mit.]=],
		},
	},
	bonds = {
		{ id = "high-inquisitor-whitemane", name = "Hochinquisitorin Whitemane", note = "teilt seinen Rang" },
	},
})

Translate("deDE", "arcanist-doan", {
	title = "Arkanist Doan",
	subtitle = "Hüter der Bibliothek",
	found = "Die innere Halle der Bibliothek des Scharlachroten Klosters",
	hint = [=[Sucht den Arkanisten, der die innere Halle der Klosterbibliothek bewacht.]=],
	allegiance = "Scharlachroter Kreuzzug",
	aliases = { "Doan" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Arkanist Doan ist der Magier, der die Bibliothek des {link:scarlet-monastery}Scharlachroten Klosters{/link} bewacht. Er hält ihre Bücher für heilige Mysterien, die kein Fremder entweihen darf. Er verbrennt Eindringlinge in dem, was er gerechtes Feuer nennt. Er bringt sie zum Schweigen, verwandelt sie in Tiere, und wenn sie ihm zu nahe kommen, hüllt er sich in eine Blase arkaner Macht und lässt sie in einer gewaltigen Explosion zerbersten.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Doan steht zwischen den Feinden des Kreuzzugs und dessen Wissen. Die Bücher, die Gelehrte aus {link:thunder-bluff}Thunder Bluff{/link}, {link:ironforge}Ironforge{/link} und {link:undercity}Undercity{/link} suchen, liegen alle hinter ihm. Der Weise {link:sage-truthseeker}Truthseeker{/link} will das Kompendium der Gefallenen, und ein Bibliothekar aus Ironforge will die Mythologie der Titanen. Ein Geschichtsschreiber aus Undercity will die Fibel, mit der der Kreuzzug seine Paladine gegen die Toten ausbildet.]=],
		},
	},
	mentions = {
		{ text = "Kompendium der Gefallenen" },
		{ text = "Mythologie der Titanen" },
		{ text = "Prüfung des Wissens" },
		{ text = "Rituals of Power" },
	},
	bonds = {
		{ id = "houndmaster-loksey", name = "Hundemeister Loksey", note = "bewacht die äußere Bibliothek" },
	},
})

Translate("deDE", "houndmaster-loksey", {
	title = "Hundemeister Loksey",
	subtitle = "Herr der scharlachroten Hunde",
