	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Hundemeister Loksey richtet die Hunde des {link:scarlet-crusade}Scharlachroten Kreuzzugs{/link} ab. Seine Tiere sind gezüchtet, um einer Fährte zu folgen, und der Kreuzzug benutzt sie, um seine Feinde durch {link:tirisfal-glades}Tirisfal{/link} zu jagen. Er hält sie in den Hallen vor der Bibliothek dicht bei sich. Wenn Feinde kommen, lässt er sie los, und er treibt sich und sein Rudel in einen Rausch.]=],
