			title = "Bedeutung",
			text = [=[Loksey zählt zu den vier obersten Leutnants des Klosters. {link:varimathras}Varimathras{/link} will ihn samt seinen dreckigen Kötern erschlagen sehen, und {link:raleigh-the-devout}Raleigh the Devout{/link} nennt ihn neben {link:high-inquisitor-whitemane}Whitemane{/link} selbst. Wer die Bibliothek erreichen will, muss zuerst an seinen Spürhunden und ihrem Herrn vorbei.]=],
