})

Translate("deDE", "bloodmage-thalnos", {
	title = "Blutmagier Thalnos",
	subtitle = "Der zornige Tote",
	found = "Die Grüfte des Friedhofs des Scharlachroten Klosters",
	hint = [=[Sucht den toten Magier, der in den Grüften des Klosterfriedhofs spukt.]=],
	allegiance = "Die ruhelosen Toten",
	aliases = { "Thalnos" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Blutmagier Thalnos ist ein toter Zauberer, der in den Grüften des Friedhofs des Scharlachroten Klosters spukt. Er dient weder dem Kreuzzug noch den Verlassenen. Er hungert nach Seelen und nach Rache, und er ruft, dass es für die zornigen Toten keine Ruhe gibt. Er schleudert Feuer und Schatten auf die Lebenden, und Flammen brechen aus ihm hervor, wenn sie ihm nahe kommen. Die Folterknechte des Kreuzzugs arbeiten nur wenige Hallen entfernt. Ob sie wissen, was in der tiefsten Gruft liegt, hat niemand gesagt.]=],
		},
		{
			title = "Nicht überliefert",
			text = [=[Keine Chronik dieser Tage verzeichnet, wer Thalnos im Leben war, wie er starb oder an wem er sich rächen will.]=],
		},
	},
	bonds = {
		{ id = "interrogator-vishas", name = "Befrager Vishas", note = "arbeitet auf demselben Friedhof" },
	},
})

Translate("deDE", "interrogator-vishas", {
	title = "Befrager Vishas",
	subtitle = "Folterknecht des Kreuzzugs",
