	allegiance = "Scharlachroter Kreuzzug",
	aliases = { "Vishas" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Befrager Vishas foltert die Gefangenen des Kreuzzugs in den Grüften des Friedhofs des Scharlachroten Klosters. Er will jedes Geheimnis, und er holt sie sich mit Feuer und Schmerz. Er ist stolz auf seine Arbeit und stolz auf seine Frau Nancy, die am Lordameresee lebt. Er schenkte ihr einen Ehering, den er einem seiner Opfer abgenommen hatte.]=],
		},
	},
	chapters = {
		{
			title = "Der gestohlene Ring",
			hint = [=[Hört den letzten Wunsch eines sterbenden Verlassenen auf dem Friedhof.]=],
			text = [=[{link:vorrel-sengutz}Vorrel Sengutz{/link} hatte wochenlang Vishas' Qualen ertragen. Als der Befrager fiel, war Vorrel froh. Ihm blieb ein Wunsch: dass Vishas' Frau für das bezahle, was ihr Mann getan hatte, und dass sein Ring heim zu seiner eigenen Frau nach {link:tarren-mill}Tarrens Mühle{/link} gehe.]=],
		},
	},
	mentions = {
		{ text = "Vorrels Rache" },
	},
	bonds = {
		{ id = "vorrel-sengutz", name = "Vorrel Sengutz", note = "sein Opfer" },
	},
})

Translate("deDE", "vorrel-sengutz", {
	title = "Vorrel Sengutz",
	subtitle = "Gefangener des Friedhofs",
	found = "Die Grüfte des Friedhofs des Scharlachroten Klosters",
	hint = [=[Sucht unter den Gefangenen des Kreuzzugs auf dem Friedhof nach einem gebrochenen Verlassenen.]=],
	allegiance = "Verlassene",
	aliases = { "Vorrel" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Vorrel Sengutz ist einer der {link:forsaken}Verlassenen{/link}, ein Toter, der mit eigenem Willen erwachte und der Dunklen Fürstin diente. Der Kreuzzug nahm ihn gefangen. {link:interrogator-vishas}Befrager Vishas{/link} folterte ihn wochenlang und stahl seinen Ehering. Nun liegt Vorrel gebrochen auf dem Friedhof. Er weiß, dass seine Zeit in der Welt zu Ende geht. Er will nur Rache, und er will, dass sein Ring seiner Frau Monika in {link:tarren-mill}Tarrens Mühle{/link} zurückgegeben wird.]=],
		},
	},
	chapters = {
		{
			title = "Sein letzter Wunsch",
			hint = "Hört den letzten Wunsch des Gefangenen.",
			text = [=[{link:interrogator-vishas}Vishas{/link} hatte mit seiner Frau Nancy geprahlt, die am Lordameresee lebte. Vorrel bat darum, dass sie gefunden und erschlagen werde und dass sein Ring zu Monika gebracht werde. Als Vishas fiel, sagte Vorrel, der Folterknecht habe bekommen, was er verdiente.]=],
		},
	},
	mentions = {
		{ text = "Vorrels Rache" },
	},
	bonds = {
		{ id = "interrogator-vishas", name = "Befrager Vishas", note = "sein Folterknecht" },
	},
})

Translate("deDE", "azshir-the-sleepless", {
	title = "Azshir the Sleepless",
	subtitle = "Wanderer des Friedhofs",
