	allegiance = "Die ruhelosen Toten",
	aliases = { "Azshir" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Azshir the Sleepless ist ein dunkler Geist, der über den {link:scarlet-monastery-graveyard}Friedhof des Scharlachroten Klosters{/link} wandert. Er bleibt nicht an einem Ort, und er ruht nicht. Er saugt den Lebenden die Seelen aus, schlägt sie mit Schrecken und ruft die Toten der Gräber herbei, damit sie für ihn kämpfen. Man sieht ihn selten. Er teilt den Friedhof mit den anderen ruhelosen Toten, nur wenige Hallen von dort entfernt, wo die Folterknechte des Kreuzzugs ihrem Handwerk nachgehen. Sein Name ist fast alles, was die Lebenden von ihm wissen.]=],
